export const GUIDE={
 'Bodyweight squat':{steps:['Stand with feet about hip-width apart and keep your whole foot grounded.','Bend at hips and knees as if sitting onto a chair.','Stand tall by pressing through your feet; breathe out as you rise.'],check:'Keep knees tracking comfortably in the direction of your toes.',easier:'Use a chair as a depth guide.'},
 'Wall or knee push-up':{steps:['Place hands slightly wider than shoulders on a wall, or start from your knees on the floor.','Keep head, torso and hips in one line as your elbows bend.','Press away slowly and finish with arms comfortably straight.'],check:'Avoid letting your lower back sag.',easier:'Move closer to the wall or use a higher surface.'},
 'Glute bridge':{steps:['Lie on your back, knees bent and feet flat, roughly hip-width apart.','Exhale and lift your hips until your body forms a gentle slope from shoulders to knees.','Pause, then lower slowly.'],check:'Lift with your hips, without arching your lower back.',easier:'Lift through a smaller comfortable range.'},
 'Standing calf raise':{steps:['Stand tall with a hand on a wall for balance.','Rise onto the balls of your feet without rolling ankles out.','Pause briefly, then lower your heels slowly.'],check:'Use control instead of bouncing.',easier:'Hold the wall with both hands.'},
 'Dead bug':{steps:['Lie on your back with knees over hips and arms toward the ceiling.','Slowly extend one leg and the opposite arm while your trunk stays still.','Return, then alternate sides.'],check:'Stop the reach before your lower back lifts.',easier:'Tap one heel down at a time, keeping arms still.'},
 'Prone W raise':{steps:['Lie face down with elbows bent into a W shape.','Draw shoulder blades gently together and lift hands slightly.','Lower slowly without straining your neck.'],check:'Keep the lift small and neck relaxed.',easier:'Try it standing, facing a wall.'},
 'Supported split squat':{steps:['Stand in a staggered stance with a hand on a wall.','Bend both knees a comfortable amount while staying upright.','Press through your front foot to stand; repeat, then switch legs.'],check:'Keep your front foot planted and avoid forcing depth.',easier:'Take a shallower bend.'},
 'Bodyweight hip hinge':{steps:['Stand with soft knees and hands on hips.','Send hips backward, keeping your back long.','Stand by gently pressing hips forward.'],check:'The movement comes from hips rather than rounding your back.',easier:'Practice reaching your hips toward a wall.'},
 'Bird dog':{steps:['Start on hands and knees, hands below shoulders and knees below hips.','Reach one arm and opposite leg away without rotating your trunk.','Return slowly, then change sides.'],check:'Keep your hips level and move only as far as you can control.',easier:'Move only an arm or only a leg.'},
 'Side plank from knees':{steps:['Lie on your side with forearm under shoulder and knees bent.','Lift hips to make a straight line from shoulders to knees.','Breathe steadily; lower with control and repeat on the other side.'],check:'Avoid shrugging into your supporting shoulder.',easier:'Hold for a shorter time.'}
};
export const requiredSets=(week,index)=>week<=2||week===13?2:week<=4||index>=3?2:3;
export function cleanStrength(value){if(!value||typeof value!=='object')return null;const counts=Array.isArray(value.counts)?Array.from({length:6},(_,i)=>{const n=value.counts[i];return Number.isInteger(n)?Math.max(0,Math.min(3,n)):0}):[0,0,0,0,0,0];return {counts};}
